const fs = require('fs');
const path = require('path');
const { randomUUID } = require('crypto');

/**
 * Express access-log middleware (no morgan).
 * Appends one JSON line per request to logs/access.jsonl:
 *   { ts, method, path, status, duration_ms, request_id }
 * The generated uuid is also sent back as the X-Request-ID header.
 */
function accessLog({ logFile = path.join(process.cwd(), 'logs', 'access.jsonl') } = {}) {
  return function accessLogMiddleware(req, res, next) {
    const start = process.hrtime.bigint();
    const request_id = randomUUID();

    res.setHeader('X-Request-ID', request_id);

    res.on('finish', () => {
      const duration_ms = Number(process.hrtime.bigint() - start) / 1e6;
      const entry = {
        ts: new Date().toISOString(),
        method: req.method,
        path: req.originalUrl || req.url,
        status: res.statusCode,
        duration_ms: Math.round(duration_ms * 1000) / 1000,
        request_id,
      };
      try {
        fs.mkdirSync(path.dirname(logFile), { recursive: true });
        fs.appendFileSync(logFile, JSON.stringify(entry) + '\n');
      } catch (err) {
        // Logging must never break the request pipeline.
        console.error('access-log write failed:', err.message);
      }
    });

    next();
  };
}

module.exports = { accessLog };
