const fs = require('fs');
const path = require('path');
const express = require('express');
const request = require('supertest');
const { randomUUID } = require('crypto');

const { accessLog } = require('../access-log');

const LOG_FILE = path.join(__dirname, '..', 'logs', 'access.jsonl');

function buildApp() {
  const app = express();
  app.use(accessLog());
  app.get('/ok', (_req, res) => res.status(200).json({ ok: true }));
  app.post('/echo', express.json(), (req, res) => res.status(201).json(req.body));
  // no route for /missing -> 404
  return app;
}

describe('access-log middleware', () => {
  beforeEach(() => {
    fs.rmSync(path.dirname(LOG_FILE), { recursive: true, force: true });
  });

  afterAll(() => {
    fs.rmSync(path.dirname(LOG_FILE), { recursive: true, force: true });
  });

  test('logs one well-formed JSON line per request with correct method/status', async () => {
    const app = buildApp();

    const r1 = await request(app).get('/ok').expect(200);
    const r2 = await request(app).get('/missing').expect(404);
    const r3 = await request(app)
      .post('/echo')
      .send({ hello: 'world' })
      .expect(201);

    // X-Request-ID header present and is a valid uuid on each response
    expect(r1.headers['x-request-id']).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
    expect(r2.headers['x-request-id']).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
    expect(r3.headers['x-request-id']).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);

    // Read the log file back
    expect(fs.existsSync(LOG_FILE)).toBe(true);
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const lines = raw.trim().split('\n');
    expect(lines).toHaveLength(3);

    const entries = lines.map((line) => JSON.parse(line)); // throws if any line is not valid JSON

    for (const e of entries) {
      expect(Object.keys(e).sort()).toEqual(
        ['duration_ms', 'method', 'path', 'request_id', 'status', 'ts'].sort()
      );
      expect(typeof e.ts).toBe('string');
      expect(!Number.isNaN(Date.parse(e.ts))).toBe(true);
      expect(e.request_id).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
      expect(Number.isFinite(e.duration_ms)).toBe(true);
      expect(e.duration_ms).toBeGreaterThanOrEqual(0);
    }

    // Correct method/status pairs, in order
    expect(entries[0]).toMatchObject({ method: 'GET', path: '/ok', status: 200 });
    expect(entries[1]).toMatchObject({ method: 'GET', path: '/missing', status: 404 });
    expect(entries[2]).toMatchObject({ method: 'POST', path: '/echo', status: 201 });

    // request_ids match what was returned in headers
    expect(entries[0].request_id).toBe(r1.headers['x-request-id']);
    expect(entries[1].request_id).toBe(r2.headers['x-request-id']);
    expect(entries[2].request_id).toBe(r3.headers['x-request-id']);
  });

  test('each request gets a unique request_id', async () => {
    const app = buildApp();
    await request(app).get('/ok').expect(200);
    await request(app).get('/ok').expect(200);

    const entries = fs.readFileSync(LOG_FILE, 'utf8').trim().split('\n').map(JSON.parse);
    expect(new Set(entries.map((e) => e.request_id)).size).toBe(2);
    expect(randomUUID()).not.toBe(entries[0].request_id); // sanity: uuids are unique
  });
});
